"""HttpClient request/event core with an injected offline transport and clock."""
from collections import deque
from modules.events import HeadersReceived, DataReceived, ConnectionTerminated, SendError


class HttpClient:
    def __init__(self, clock, backend, timeout_ms):
        self._loop = clock
        self._http = backend
        self._quic = backend
        self._timeout_ms = timeout_ms
        self._request_events = {}
        self._request_waiter = {}
        self._request_timeout_handlers = {}
        self._pauses = {}
        self._sending = {}
        self._response_ended = set()
        self._close_info = None

    def _log(self, msg):
        pass

    async def request(self, Case, case_index):
        stream_id = self._quic.get_next_available_stream_id()
        self._request_events[stream_id] = deque()
        self._sending[stream_id] = True
        state = 'ok'
        try:
            for item in Case:
                if self._close_info is not None:
                    raise ConnectionError(self._close_info)
                if item['Type'] == 'headers':
                    self._http.send_headers(stream_id=stream_id,
                        headers=item['data_to_transfered'],end_stream=item['End_Stream'])
                elif item['Type'] == 'data':
                    self._http.send_data(stream_id=stream_id,
                        data=item['data_to_transfered'],end_stream=item['End_Stream'])
                elif item['Type'] == 'datagram':
                    self._http.send_datagram(stream_id=stream_id,data=item['data_to_transfered'])
                elif item['Type'] == 'sleep':
                    pause = self._loop.sleep(item['Time_to_Stop'],case_index)
                    self._pauses[stream_id] = pause
                    await pause
                    self._pauses.pop(stream_id,None)
                    continue
                self.transmit()
            self._sending[stream_id] = False
            waiter = self._loop.create_future()
            self._request_waiter[stream_id] = waiter
            deadline = self._loop.now + self._timeout_ms
            self._request_timeout_handlers[stream_id] = deadline
            self._loop.schedule(deadline,2,case_index,
                lambda sid=stream_id:self._handle_request_timeout(sid))
            await waiter
        except ConnectionError:
            state = 'closed'
        except TimeoutError:
            state = 'timeout'
        except SendError:
            state = 'send_error'
        events = list(self._request_events.pop(stream_id,()))
        self._request_waiter.pop(stream_id,None)
        self._request_timeout_handlers.pop(stream_id,None)
        self._pauses.pop(stream_id,None)
        self._sending.pop(stream_id,None)
        return {'state':state,'at':self._loop.now,'events':events,'stream':stream_id}

    def transmit(self):
        return None

    def _handle_request_timeout(self, stream_id):
        if stream_id in self._request_waiter and not self._request_waiter[stream_id].done():
            self._cancel_request(stream_id,'Time Out')

    def _cancel_request(self, stream_id, reason):
        if stream_id in self._request_waiter:
            waiter = self._request_waiter[stream_id]
            if not waiter.done():
                waiter.set_exception(TimeoutError(reason))

    def http_event_received(self, event):
        stream_id = event.stream_id
        if stream_id in self._request_events and stream_id not in self._response_ended:
            self._request_events[stream_id].append((self._loop.now,event))
            if event.stream_ended:
                self._response_ended.add(stream_id)
                if not self._sending[stream_id]:
                    waiter = self._request_waiter[stream_id]
                    if not waiter.done():
                        waiter.set_result(None)

    def quic_event_received(self, event):
        if isinstance(event,ConnectionTerminated):
            self._close_info = event.reason_phrase
            for stream_id, waiter in list(self._request_waiter.items()):
                if not waiter.done():
                    waiter.set_exception(ConnectionError(self._close_info))
            for stream_id, pause in list(self._pauses.items()):
                if not pause.done():
                    pause.set_exception(ConnectionError(self._close_info))
        else:
            self.http_event_received(event)

    def connection_lost(self, exc=None):
        self.quic_event_received(ConnectionTerminated(reason_phrase='Connection lost'))
"""Public sanity checker: bounded child CLI, no private inputs and no score."""
import json
import math
import os
from pathlib import Path
import selectors
import signal
import stat
import subprocess
import sys
import time

HERE = Path(__file__).resolve().parent


class CandidateFailure(Exception):
    pass


class InfrastructureError(Exception):
    pass


def unique_object(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate output key')
        out[k] = v
    return out


def invalid_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError('nonfinite JSON number')
    return value


def parse_output(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object,
                      parse_constant=invalid_constant, parse_float=finite_float)


def canonical(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=True, separators=(',', ':'), allow_nan=False)


def storage_over_budget(scratch):
    total = entries = 0
    stack = [scratch]
    while stack:
        p = stack.pop()
        try:
            s = p.lstat()
            entries += 1
            if stat.S_ISREG(s.st_mode):
                total += max(s.st_size, s.st_blocks*512)
            elif stat.S_ISDIR(s.st_mode):
                with os.scandir(p) as children:
                    stack.extend(Path(e.path) for e in children)
        except FileNotFoundError:
            continue
        if total > 1024**3 or entries > 50000:
            return True
    return False


def invoke(candidate, raw):
    if os.geteuid() == 0:
        raise InfrastructureError('refusing root candidate execution; use the image default user')
    scratch = Path('/workspace/tmp')
    # The public image owns this dedicated directory; the private worker also
    # clears it before invocation. Only remove scratch entries, never submissions.
    import shutil
    for entry in scratch.iterdir():
        if entry.is_dir() and not entry.is_symlink():
            shutil.rmtree(entry)
        else:
            entry.unlink()
    env = {'PATH':'/usr/local/bin:/usr/bin:/bin', 'LANG':'C', 'LC_ALL':'C',
           'HOME':'/workspace', 'TMPDIR':str(scratch), 'PYTHONHASHSEED':'0',
           'PYTHONUNBUFFERED':'1', 'PYTHONDONTWRITEBYTECODE':'1',
           'OPENBLAS_NUM_THREADS':'1', 'OMP_NUM_THREADS':'1', 'MKL_NUM_THREADS':'1'}
    p = None
    sel = selectors.DefaultSelector()
    streams = []
    buffers = [bytearray(), bytearray()]
    limits = [16*1024**2, 1024**2]
    offset = 0
    deadline = time.monotonic()+60
    next_storage = 0
    try:
        previous = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGTERM, signal.SIGINT})
        try:
            p = subprocess.Popen([sys.executable, '-I', '-B', str(HERE/'runner.py'), str(candidate)],
                                 stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 cwd='/workspace', env=env, close_fds=True)
            streams = [p.stdin, p.stdout, p.stderr]
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, previous)
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if raw:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while sel.get_map():
            now = time.monotonic()
            if now >= deadline:
                raise CandidateFailure('wall timeout')
            if now >= next_storage:
                if storage_over_budget(scratch):
                    raise InfrastructureError('scratch emergency brake; no score')
                next_storage = now+.25
            for key, _ in sel.select(min(.1, deadline-now)):
                stream, kind = key.fileobj, key.data
                if kind == -1:
                    try:
                        n = os.write(stream.fileno(), memoryview(raw)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(stream)
                        stream.close()
                        continue
                    offset += n
                    if offset == len(raw):
                        sel.unregister(stream)
                        stream.close()
                else:
                    try:
                        block = os.read(stream.fileno(), min(65536,limits[kind]-len(buffers[kind])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(buffers[kind])+len(block) > limits[kind]:
                        raise CandidateFailure(('stdout','stderr')[kind]+' limit')
                    else:
                        buffers[kind].extend(block)
        try:
            code = p.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired:
            raise CandidateFailure('wall timeout') from None
        if code:
            raise CandidateFailure('nonzero exit status')
        try:
            return parse_output(bytes(buffers[0]))
        except (UnicodeError, ValueError, RecursionError):
            raise CandidateFailure('missing or malformed JSON output') from None
    finally:
        # Candidate code starts only after no-fork seccomp is installed.
        if p is not None:
            if p.poll() is None:
                p.kill()
            p.wait(timeout=5)
        sel.close()
        for stream in streams:
            stream.close()


def interrupted(signum, frame):
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    raise KeyboardInterrupt()


def main():
    for sig in (signal.SIGTERM, signal.SIGINT):
        signal.signal(sig, interrupted)
    if len(sys.argv) != 2:
        raise SystemExit('usage: python3 check.py /workspace/project')
    candidate = Path(sys.argv[1]).absolute() / 'main.py'
    s = candidate.lstat()
    if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_size > 8*1024*1024:
        raise SystemExit('submission file must be regular, one link, at most 8 MiB')
    fixtures = json.loads((HERE/'examples.json').read_text())
    try:
        for row in fixtures:
            value = invoke(candidate, row['stdin'].encode('utf-8'))
            try:
                actual = canonical(value)
            except (ValueError, RecursionError, OverflowError):
                raise CandidateFailure('malformed JSON output') from None
            if actual != canonical(row['expected']):
                raise CandidateFailure(row['name']+': output differs from public expectation')
    except KeyboardInterrupt:
        print('INTERRUPTED: no result', file=sys.stderr)
        return 130
    except CandidateFailure as e:
        print('FAIL: '+str(e), file=sys.stderr)
        return 1
    except InfrastructureError as e:
        print('INFRASTRUCTURE ERROR: '+str(e), file=sys.stderr)
        return 2
    print('PASS: '+str(len(fixtures))+' public CLI fixtures (no score)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
"""Public Linux x86-64 resource/syscall adapter. Invoked by check.py as nonroot."""
import ctypes
import os
import platform
import resource
import signal
import sys

# x86-64 syscall numbers, matching the public PROTOCOL.md deny list.
DENIED = [41,53,42,29,30,31,64,65,66,220,68,69,70,71,62,200,234,101,
          310,311,272,308,165,166,155,161,112,109,105,106,113,114,117,119,
          116,304,303,321,250,248,249,298,323,425,426,427,438,57,58,56]


class Filter(ctypes.Structure):
    _fields_ = [('code', ctypes.c_ushort), ('jt', ctypes.c_ubyte),
                ('jf', ctypes.c_ubyte), ('k', ctypes.c_uint)]


class Program(ctypes.Structure):
    _fields_ = [('len', ctypes.c_ushort), ('filter', ctypes.POINTER(Filter))]


def restrict():
    if os.geteuid() == 0 or platform.machine() != 'x86_64':
        raise RuntimeError('nonroot Linux x86-64 required')
    for what, limits in [(resource.RLIMIT_AS, (512*1024**2,)*2),
                         (resource.RLIMIT_CPU, (20,21)),
                         (resource.RLIMIT_NOFILE, (32,32)),
                         (resource.RLIMIT_NPROC, (64,64)),
                         (resource.RLIMIT_FSIZE, (64*1024**2,)*2),
                         (resource.RLIMIT_STACK, (8*1024**2,)*2),
                         (resource.RLIMIT_CORE, (0,0))]:
        resource.setrlimit(what, limits)
    instructions = [(0x20,0,0,4), (0x15,1,0,0xc000003e), (0x06,0,0,0x80000000),
                    (0x20,0,0,0), (0x35,0,1,0x40000000), (0x06,0,0,0x80000000)]
    for number in DENIED:
        instructions.extend([(0x15,0,1,number),(0x06,0,0,0x50000 | 1)])
    instructions.extend([(0x15,0,1,435),(0x06,0,0,0x50000 | 38), (0x06,0,0,0x7fff0000)])
    filters = (Filter * len(instructions))(*(Filter(*x) for x in instructions))
    program = Program(len(instructions), filters)
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(4,0,0,0,0) or libc.prctl(38,1,0,0,0) or libc.prctl(22,2,ctypes.byref(program),0,0):
        raise OSError(ctypes.get_errno(), 'seccomp setup failed')


if __name__ == '__main__':
    os.chdir(os.path.dirname(os.path.abspath(sys.argv[1])))
    restrict()
    signal.pthread_sigmask(signal.SIG_UNBLOCK, {signal.SIGTERM, signal.SIGINT})
    os.execv(sys.executable, [sys.executable, '-B', sys.argv[1]])
